import { useState, useEffect } from 'react';
import LineChart from './LineChart';
import StatCard from './StatCard';

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    setIsLoaded(true);
  }, []);

  // Mock data for the chart and stats
  const mockRevenueData = [
    12000, 14500, 16000, 18000, 20000, 22000, 24000, 26000, 28000, 30000, 32000, 34000
  ];

  const mockStats = [
    { label: 'Revenue', value: '$24,000', trend: 'up', change: 12 },
    { label: 'Users', value: '12,500', trend: 'up', change: 8 },
    { label: 'Orders', value: '2,450', trend: 'down', change: 3 },
    { label: 'Churn', value: '1.2%', trend: 'down', change: -2 }
  ];

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-3xl font-bold text-gray-800 mb-8">Dashboard</h1>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          {mockStats.map((stat, index) => (
            <StatCard key={index} stat={stat} />
          ))}
        </div>

        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-2xl font-semibold text-gray-800 mb-6">Monthly Revenue</h2>
          <LineChart data={mockRevenueData} />
        </div>
      </div>
    </div>
  );
};

export default App;
