### LineChart.tsx
```tsx
import { useState, useEffect } from 'react';

interface ChartData {
  x: number;
  y: number;
}

interface LineChartProps {
  data: number[];
}

const LineChart = ({ data }: LineChartProps) => {
  const [points, setPoints] = useState<ChartData[]>([]);

  useEffect(() => {
    const chartPoints = data.map((value, index) => ({
      x: index,
      y: value,
    }));
    setPoints(chartPoints);
  }, [data]);

  return (
    <div className="h-64 relative">
      <svg width="100%" height="100%" viewBox="0 0 100 40" className="overflow-visible">
        {/* Grid lines */}
        {Array.from({ length: 5 }, (_, i) => (
          <line
            key={i}
            x1="0"
            y1={40 - (i * 8)}
            x2="100"
            y2={40 - (i * 8)}
            stroke="#e5e7eb"
            strokeWidth="1"
            opacity="0.5"
          />
        ))}

        {/* X-axis labels */}
        {Array.from({ length: 12 }, (_, i) => (
          <text
            key={i}
            x={100 * i / 11}
            y="38"
            fill="#6b7280"
            fontSize="10"
            textAnchor="middle"
            className="fill-gray-500"
          >
            {i + 1}
          </text>
        ))}

        {/* Y-axis labels */}
        {Array.from({ length: 5 }, (_, i) => (
          <text
            key={i}
            x="0"
            y={40 - (i * 8)}
            fill="#6b7280"
            fontSize="10"
            textAnchor="start"
            className="fill-gray-500"
          >
            {i === 0 ? '34k' : i === 1 ? '30k' : i === 2 ? '26k' : i === 3 ? '22k' : '18k'}
          </text>
        ))}

        {/* Line path */}
        <polyline
          fill="none"
          stroke="#047857"
          strokeWidth="3"
          points={points.map(p => `${p.x * 100 / 11},${40 - (p.y / 34000) * 30}`).join(' ')}
          className="stroke-accent"
        />

        {/* Data points */}
        {points.map((p, i) => (
          <circle
            key={i}
            cx={p.x * 100 / 11}
            cy={40 - (p.y / 34000) * 30}
            r="4"
            fill="#047857"
            opacity="0.8"
          />
        ))}
      </svg>
    </div>
  );
};

export default LineChart;
```

### StatCard.tsx
```tsx
import React from 'react';

interface StatCardProps {
  stat: {
    label: string;
    value: string;
    trend: 'up' | 'down';
    change: number;
  };
}

const StatCard = ({ stat }: StatCardProps) => {
  const trendIcon = stat.trend === 'up' ? '↑' : '↓';
  const trendColor = stat.trend === 'up' ? 'text-green-500' : 'text-red-500';

  return (
    <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 hover:shadow-md transition-shadow duration-200">
      <div className="flex justify-between items-start">
        <div>
          <h3 className="text-sm font-medium text-gray-500">{stat.label}</h3>
          <p className="text-2xl font-bold text-gray-800 mt-1">{stat.value}</p>
        </div>
        <div className={`flex items-center text-sm ${trendColor}`}>
          {trendIcon} <span className="ml-1">{stat.change > 0 ? '+' : ''}{stat.change}%</span>
        </div>
      </div>
    </div>
  );
};

export default StatCard;
```
